78	impl TarballWrite {
79	    pub async fn write_all(&mut self, bytes: &[u8]) -> std::io::Result<()> {
80	        match self.file.as_mut() {
81	            Some(file) => file.write_all(bytes).await,
82	            None => Err(std::io::Error::other("tarball cache writer is closed")),
83	        }
84	    }
85	
86	    /// Sync the file to disk and rename it to its final cache path.
87	    pub async fn finalize(mut self) -> std::io::Result<()> {
88	        match self.file.as_mut() {
89	            Some(file) => file.sync_all().await?,
90	            None => return Err(std::io::Error::other("tarball cache writer is closed")),
91	        }
92	        drop(self.file.take());
93	        if let Some(parent) = self.final_path.parent() {
94	            fs::create_dir_all(parent).await?;
95	        }
96	        let tmp_path = self
97	            .tmp_path
98	            .as_ref()
99	            .ok_or_else(|| std::io::Error::other("tarball cache temp path is missing"))?;
100	        fs::rename(tmp_path, &self.final_path).await?;
101	        self.tmp_path = None;
102	        Ok(())
103	    }
104	
105	    /// Rewind the verified write handle so the caller streams the exact
106	    /// bytes that were hashed. The handle is opened read+write up front
107	    /// and reused here — never dropped and reopened by path — so there is
108	    /// no window for an attacker-writable cache directory to swap the
109	    /// temp file between verification and streaming.
110	    pub async fn into_temp_file(mut self) -> std::io::Result<(fs::File, u64, PathBuf)> {
111	        let Some(mut file) = self.file.take() else {
112	            return Err(std::io::Error::other("tarball cache writer is closed"));
113	        };
114	        file.sync_all().await?;
115	        let len = file.metadata().await?.len();
116	        let tmp_path = self
117	            .tmp_path
118	            .take()
119	            .ok_or_else(|| std::io::Error::other("tarball cache temp path is missing"))?;
120	        file.seek(SeekFrom::Start(0)).await?;
121	        Ok((file, len, tmp_path))
122	    }
123	
124	    pub async fn abandon(mut self) {
125	        drop(self.file.take());
126	        let Some(tmp_path) = self.tmp_path.as_ref() else { return };
127	        match fs::remove_file(tmp_path).await {
128	            Ok(()) => self.tmp_path = None,
129	            Err(err) if err.kind() == ErrorKind::NotFound => self.tmp_path = None,
130	            Err(_) => {}
131	        }
132	    }
133	}
