149	/// A cached upstream packument, read at a granularity that avoids loading
150	/// the (potentially multi-MB) body when it isn't needed:
151	///
152	/// * `Fresh` — within the TTL; the body is read and ready to serve.
153	/// * `Stale` — past the TTL; only the small conditional-GET validators
154	///   (one set per uplink in the package's fallback chain) are loaded. The
155	///   body is left on disk and pulled on demand by the caller (via
156	///   [`Storage::read_cached_packument`]) only if the upstream answers `304`
157	///   or is unreachable — the common stale→`200` refresh discards the old
158	///   body, so it's never read.
159	#[derive(Debug)]
160	pub enum CachedPackument {
161	    Fresh(Vec<u8>),
162	    Stale(ValidatorsByUplink),
163	}
164	
165	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
166	pub struct CachedTarballIntegrity {
167	    pub integrity: String,
168	    pub len: u64,
169	}
170	
171	/// Verdaccio-shaped storage split into two stores with different
172	/// durability guarantees:
173	///
174	/// * `hosted` — the authoritative source of truth: packages this
175	///   server hosts directly (published through its API) plus the content
176	///   served in static mode. Served as-is and never overwritten by an
177	///   upstream refresh, so a hosted version can't be masked or lost.
178	///   Backed by a local directory by default, or an S3-compatible
179	///   object store (S3, Cloudflare R2, `MinIO`, ...) when the YAML `s3:`
180	///   block is set — see [`crate::s3`].
181	/// * `cached` — the disposable mirror of upstream registries. Safe to
182	///   wipe at any time; it self-heals on the next request. Always local,
183	///   on scratch/ephemeral disk.
184	///
185	/// Both use the same logical layout:
186	///
187	/// ```text
188	/// <root>/
189	///   <package>/
190	///     package.json
191	///     <basename>-<version>.tgz
192	/// ```
193	///
194	/// For scoped packages the package directory is `<root>/@scope/<name>/`.
195	/// Tarballs sit flat alongside `package.json` — no `-/` subdirectory.
196	/// This is the layout `@pnpm/registry-mock` (and verdaccio itself)
197	/// publishes, so a populated verdaccio storage can be served directly
198	/// in static mode.
199	#[derive(Debug, Clone)]
200	pub struct Storage {
201	    hosted: HostedStore,
202	    cached: Store,
203	}
204	
205	/// The hosted store's pluggable backend: a local directory or an
206	/// S3-compatible bucket. The disposable `cached` store is always
207	/// local, so only the hosted side varies.
208	#[derive(Debug, Clone)]
